class BlpImageFile(ImageFile.ImageFile):
    def _open(self):
        self.magic = self.fp.read(4)
        self._read_blp_header()
        if self.magic == b"BLP1":
            decoder = "BLP1"
            self.mode = "RGB"
        elif self.magic == b"BLP2":
            decoder = "BLP2"
            self.mode = "RGBA" if self._blp_alpha_depth else "RGB"
        else:
            raise BLPFormatError(f"Bad BLP magic {repr(self.magic)}")
        self.tile = [(decoder, (0, 0) + self.size, 0, (self.mode, 0, 1))]
class _BLPBaseDecoder(ImageFile.PyDecoder):
    def _read_palette(self):
        ret = []
        for i in range(256):
            try:
                b, g, r, a = struct.unpack("<4B", self.fd.read(4))
            except struct.error:
                break
            ret.append((b, g, r, a))
        return ret
    def _read_blp_header(self):
        (self._blp_compression,) = struct.unpack("<i", self.fd.read(4))
        (self._blp_encoding,) = struct.unpack("<b", self.fd.read(1))
        (self._blp_alpha_depth,) = struct.unpack("<b", self.fd.read(1))
        (self._blp_alpha_encoding,) = struct.unpack("<b", self.fd.read(1))
        (self._blp_mips,) = struct.unpack("<b", self.fd.read(1))
        self.size = struct.unpack("<II", self.fd.read(8))
        if self.magic == b"BLP1":
            (self._blp_encoding,) = struct.unpack("<i", self.fd.read(4))
            (self._blp_subtype,) = struct.unpack("<i", self.fd.read(4))
        self._blp_offsets = struct.unpack("<16I", self.fd.read(16 * 4))
        self._blp_lengths = struct.unpack("<16I", self.fd.read(16 * 4))
class BLP1Decoder(_BLPBaseDecoder):
    def _load(self):
        if self._blp_compression == BLP_FORMAT_JPEG:
            self._decode_jpeg_stream()
        elif self._blp_compression == 1:
            if self._blp_encoding in (4, 5):
                data = bytearray()
                palette = self._read_palette()
                _data = BytesIO(self.fd.read(self._blp_lengths[0]))
                while True:
                    try:
                        (offset,) = struct.unpack("<B", _data.read(1))
                    except struct.error:
                        break
                    b, g, r, a = palette[offset]
                    data.extend([r, g, b])
                self.set_as_raw(bytes(data))
            else:
                raise BLPFormatError(
                    f"Unsupported BLP encoding {repr(self._blp_encoding)}"
                )
        else:
            raise BLPFormatError(
                f"Unsupported BLP compression {repr(self._blp_encoding)}"
            )
    def _decode_jpeg_stream(self):
        from PIL.JpegImagePlugin import JpegImageFile
        (jpeg_header_size,) = struct.unpack("<I", self.fd.read(4))
        jpeg_header = self.fd.read(jpeg_header_size)
        self.fd.read(self._blp_offsets[0] - self.fd.tell())
        data = self.fd.read(self._blp_lengths[0])
        data = jpeg_header + data
        data = BytesIO(data)
        image = JpegImageFile(data)
