def make_graph(db_name, room_id, file_prefix, limit):
    conn = sqlite3.connect(db_name)
    sql = (
        "SELECT json FROM event_json as j "
        "INNER JOIN events as e ON e.event_id = j.event_id "
        "WHERE j.room_id = ?"
    )
    args = [room_id]
    if limit:
        sql += (
            " ORDER BY topological_ordering DESC, stream_ordering DESC "
            "LIMIT ?"
        )
        args.append(limit)
    c = conn.execute(sql, args)
    events = [FrozenEvent(json.loads(e[0])) for e in c.fetchall()]
    events.sort(key=lambda e: e.depth)
    node_map = {}
    state_groups = {}
    graph = pydot.Dot(graph_name="Test")
    for event in events:
        c = conn.execute(
            "SELECT state_group FROM event_to_state_groups "
            "WHERE event_id = ?",
            (event.event_id,)
        )
        res = c.fetchone()
        state_group = res[0] if res else None
        if state_group is not None:
            state_groups.setdefault(state_group, []).append(event.event_id)
        t = datetime.datetime.fromtimestamp(
            float(event.origin_server_ts) / 1000
        ).strftime('%Y-%m-%d %H:%M:%S,%f')
        content = json.dumps(unfreeze(event.get_dict()["content"]))
        label = (
            "<"
            "<b>%(name)s </b><br/>"
            "Type: <b>%(type)s </b><br/>"
            "State key: <b>%(state_key)s </b><br/>"
            "Content: <b>%(content)s </b><br/>"
            "Time: <b>%(time)s </b><br/>"
            "Depth: <b>%(depth)s </b><br/>"
            "State group: %(state_group)s<br/>"
            ">"
        ) % {
            "name": event.event_id,
            "type": event.type,
            "state_key": event.get("state_key", None),
            "content": cgi.escape(content, quote=True),
            "time": t,
            "depth": event.depth,
            "state_group": state_group,
        }
        node = pydot.Node(
            name=event.event_id,
            label=label,
        )
        node_map[event.event_id] = node
        graph.add_node(node)
    for event in events:
        for prev_id, _ in event.prev_events:
            try:
                end_node = node_map[prev_id]
            except:
                end_node = pydot.Node(
                    name=prev_id,
                    label="<<b>%s</b>>" % (prev_id,),
                )
                node_map[prev_id] = end_node
                graph.add_node(end_node)
            edge = pydot.Edge(node_map[event.event_id], end_node)
            graph.add_edge(edge)
    for group, event_ids in state_groups.items():
        if len(event_ids) <= 1:
            continue
        cluster = pydot.Cluster(
            str(group),
            label="<State Group: %s>" % (str(group),)
        )
        for event_id in event_ids:
            cluster.add_node(node_map[event_id])
        graph.add_subgraph(cluster)
    graph.write('%s.dot' % file_prefix, format='raw', prog='dot')
    graph.write_svg("%s.svg" % file_prefix, prog='dot')
    make_graph(args.db, args.room, args.prefix, args.limit)
def assert_params_in_request(body, required):
    absent = []
    for k in required:
        if k not in body:
            absent.append(k)
    if len(absent) > 0:
        raise SynapseError(400, "Missing params: %r" % absent, Codes.MISSING_PARAM)

def event_from_pdu_json(pdu_json, outlier=False):
    """Construct a FrozenEvent from an event json received over federation
    Args:
        pdu_json (object): pdu as received over federation
        outlier (bool): True to mark this event as an outlier
    Returns:
        FrozenEvent
    Raises:
        SynapseError: if the pdu is missing required fields or is otherwise
            not a valid matrix event
    """
    assert_params_in_request(pdu_json, ('event_id', 'type', 'depth'))
    depth = pdu_json['depth']
    if not isinstance(depth, six.integer_types):
        raise SynapseError(400, "Depth %r not an intger" % (depth, ),
                           Codes.BAD_JSON)
    if depth < 0:
        raise SynapseError(400, "Depth too small", Codes.BAD_JSON)
    elif depth > MAX_DEPTH:
        raise SynapseError(400, "Depth too large", Codes.BAD_JSON)
    event = FrozenEvent(
        pdu_json
    )
    event.internal_metadata.outlier = outlier
    return event
class FrozenEvent(EventBase):
    @staticmethod
    def from_event(event):
        e = FrozenEvent(
            event.get_pdu_json()
        )
        e.internal_metadata = event.internal_metadata
        return e
class EventsWorkerStore(SQLBaseStore):
    @defer.inlineCallbacks
    def _get_event_from_row(self, internal_metadata, js, redacted,
                            rejected_reason=None):
        with Measure(self._clock, "_get_event_from_row"):
            d = json.loads(js)
            internal_metadata = json.loads(internal_metadata)
            if rejected_reason:
                rejected_reason = yield self._simple_select_one_onecol(
                    table="rejections",
                    keyvalues={"event_id": rejected_reason},
                    retcol="reason",
                    desc="_get_event_from_row_rejected_reason",
                )
            original_ev = FrozenEvent(
                d,
                internal_metadata_dict=internal_metadata,
                rejected_reason=rejected_reason,
            )
            redacted_event = None
            if redacted:
                redacted_event = prune_event(original_ev)
                redaction_id = yield self._simple_select_one_onecol(
                    table="redactions",
                    keyvalues={"redacts": redacted_event.event_id},
                    retcol="event_id",
                    desc="_get_event_from_row_redactions",
                )
                redacted_event.unsigned["redacted_by"] = redaction_id
                because = yield self.get_event(
                    redaction_id,
                    check_redacted=False,
                    allow_none=True,
                )
                if because:
                    redacted_event.unsigned["redacted_because"] = because
            cache_entry = _EventCacheEntry(
                event=original_ev,
                redacted_event=redacted_event,
            )
            self._get_event_cache.prefill((original_ev.event_id,), cache_entry)
        defer.returnValue(cache_entry)
