class MercurialRepo(BaseRepo):
    def obtain(self):
        self.ensure_dir()
        self.run(["clone", "--noupdate", "-q", self.url, self.path])
        self.run(["update", "-q"])
    def update_repo(self):
        self.ensure_dir()
        if not os.path.isdir(os.path.join(self.path, ".hg")):
            self.obtain()
            self.update_repo()
        else:
            self.run(["update"])
            self.run(["pull", "-u"])

class MercurialRepo(BaseRepo):
    def obtain(self):
        self.ensure_dir()
