        hkey = k[:_inbytes(self.keysize)]
        dkey = k[_inbytes(self.keysize):]
        if not constant_time.bytes_eq(t, self._mac(hkey, a, iv, e)):
            raise InvalidSignature('Failed to verify MAC')
