class AlreadyExists(HorizonException):
class HandledException(HorizonException):
UNAUTHORIZED += tuple(EXCEPTION_CONFIG.get('unauthorized', []))
NOT_FOUND += tuple(EXCEPTION_CONFIG.get('not_found', []))
