log = Logger()
class NicotineCore:
    def initiate_connection_to_peer(self, user, message, address=None):
        """ Prepare to initiate a connection with a peer """
        if message.__class__ is slskmessages.FileRequest:
            message_type = 'F'
        elif message.__class__ is slskmessages.DistribRequest:
            message_type = 'D'
        else:
            message_type = 'P'
        init = slskmessages.PeerInit(
            init_user=config.sections["server"]["login"], target_user=user, conn_type=message_type, token=0)
        addr = None
        if user == config.sections["server"]["login"]:
            addr = (self.protothread.bindip or '127.0.0.1', self.protothread.listenport)
        elif user in self.users:
            addr = self.users[user].addr
        elif address is not None:
            self.users[user] = UserAddr(status=-1, addr=address)
            addr = address
        if addr is None:
            self.queue.append(slskmessages.GetPeerAddress(user))
            log.add_conn("Requesting address for user %(user)s", {
                'user': user
            })
        else:
            self.connect_to_peer_direct(user, addr, message_type, init)
        self.peerconns.append(
            PeerConnection(
                addr=addr,
                username=user,
                msgs=[message],
                init=init
            )
        )
    def connect_to_peer_direct(self, user, addr, message_type, init=None):
        """ Initiate a connection with a peer directly """
        self.queue.append(slskmessages.InitPeerConn(None, addr, init))
        log.add_conn("Attempting direct connection of type %(type)s to user %(user)s %(addr)s", {
            'type': message_type,
            'user': user,
            'addr': addr
        })
    def login(self, msg):
        """ Server code: 1 """
        log.add_msg_contents(msg)
        if msg.success:
            self.exit.clear()
            thread = threading.Thread(target=self._check_indirect_connection_timeouts)
            thread.name = "IndirectConnectionTimeoutTimer"
            thread.daemon = True
            thread.start()
            self.logged_in = True
            self.set_away_mode(config.sections["server"]["away"])
            self.watch_user(config.sections["server"]["login"])
            if msg.ip_address is not None:
                self.user_ip_address = msg.ip_address
            self.transfers.server_login()
            self.userbrowse.server_login()
            self.userinfo.server_login()
            self.userlist.server_login()
            self.privatechats.server_login()
            self.chatrooms.server_login()
            if self.ui_callback:
                self.ui_callback.server_login()
            if msg.banner:
                log.add(msg.banner)
            self.interests.server_login()
            self.queue.append(slskmessages.CheckPrivileges())
            self.send_have_no_parent()
            """ TODO: We can currently receive search requests from a parent connection, but
            redirecting results to children is not implemented yet. Tell the server we don't accept
            children for now. """
            self.queue.append(slskmessages.AcceptChildren(0))
            self.shares.send_num_shared_folders_files()
            """ Request a complete room list. A limited room list not including blacklisted rooms and
            rooms with few users is automatically sent when logging in, but subsequent room list
            requests contain all rooms. """
            self.queue.append(slskmessages.RoomList())
            self.queue.append(slskmessages.PrivateRoomToggle(config.sections["server"]["private_chatrooms"]))
            self.pluginhandler.server_connect_notification()
        else:
            self.manual_disconnect = True
            self.queue.append(slskmessages.ConnClose(self.server_conn))
            if msg.reason == "INVALIDPASS":
                self.ui_callback.invalid_password()
                return
            log.add_important_error(_("Unable to connect to the server. Reason: %s"), msg.reason)
class Transfers:
    def get_file(self, user, filename, path="", transfer=None, size=None, bitrate=None, length=None):
        path = clean_path(path, absolute=True)
        if transfer is None:
            for i in self.downloads:
                if i.user == user and i.filename == filename and i.path == path:
                    if i.status == "Finished":
                        transfer = i
                        break
                    return
            transfer = Transfer(
                user=user, filename=filename, path=path,
                status="Queued", size=size, bitrate=bitrate,
                length=length
            )
            self.downloads.appendleft(transfer)
        else:
            transfer.filename = filename
            transfer.status = "Queued"
        self.core.watch_user(user)
        if self.config.sections["transfers"]["enablefilters"]:
            try:
                downloadregexp = re.compile(self.config.sections["transfers"]["downloadregexp"], re.I)
                if downloadregexp.search(filename) is not None:
                    log.add_transfer("Filtering: %s", filename)
                    self.abort_transfer(transfer)
                    transfer.status = "Filtered"
                    if self.auto_clear_download(transfer):
                        return
            except Exception:
                pass
        if self.user_logged_out(user):
            transfer.status = "User logged off"
        elif transfer.status != "Filtered":
            download_path = self.get_existing_download_path(user, filename, path, size)
            if download_path:
                transfer.status = "Finished"
                transfer.size = transfer.currentbytes = size
                log.add_transfer("File %s is already downloaded", download_path)
            else:
                log.add_transfer("Adding file %(filename)s from user %(user)s to download queue", {
                    "filename": filename,
                    "user": user
                })
                self.core.send_message_to_peer(
                    user, slskmessages.QueueUpload(None, filename, transfer.legacy_attempt))
        if self.downloadsview:
            self.downloadsview.update(transfer)
class SlskProtoThread(threading.Thread):
    @staticmethod
    def pack_network_message(msg_obj):
        try:
            return msg_obj.make_network_message()
        except Exception:
            from traceback import format_exc
            log.add(("Unable to pack message type %(msg_type)s. %(error)s"),
                    {'msg_type': msg_obj.__class__, 'error': format_exc()})
        return None
    def process_peer_init_output(self, msg_obj):
        if msg_obj.conn not in self._conns:
            log.add_conn("Can't send the message over the closed connection: %(type)s %(msg_obj)s", {
                'type': msg_obj.__class__,
                'msg_obj': vars(msg_obj)
            })
            return
        if msg_obj.__class__ is PierceFireWall:
            conn_obj = self._conns[msg_obj.conn]
            msg = self.pack_network_message(msg_obj)
            if msg is None:
                return
            conn_obj.piercefw = msg_obj
            conn_obj.obuf.extend(UINT_PACK(len(msg) + 1))
            conn_obj.obuf.extend(bytes([self.peerinitcodes[msg_obj.__class__]]))
            conn_obj.obuf.extend(msg)
        elif msg_obj.__class__ is PeerInit:
            conn_obj = self._conns[msg_obj.conn]
            msg = self.pack_network_message(msg_obj)
            if msg is None:
                return
            conn_obj.init = msg_obj
            if conn_obj.piercefw is not None:
                return
            conn_obj.obuf.extend(UINT_PACK(len(msg) + 1))
            conn_obj.obuf.extend(bytes([self.peerinitcodes[msg_obj.__class__]]))
            conn_obj.obuf.extend(msg)
        self.modify_connection_events(conn_obj, selectors.EVENT_READ | selectors.EVENT_WRITE)
    def process_conn_input(self, connection, conn_obj):
        if connection is self.server_socket:
            self.process_server_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is None:
            self.process_peer_init_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'P':
            self.process_peer_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'F':
            self.process_file_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'D':
            self.process_distrib_input(conn_obj, conn_obj.ibuf)
        else:
            log.add("Can't handle connection type %s", conn_obj.init.conn_type)
def open_file_path(file_path, command=None):
    """ Currently used to either open a folder or play an audio file
    Tries to run a user-specified command first, and falls back to
    the system default. """
    try:
        file_path = os.path.normpath(file_path)
        if command and "$" in command:
            execute_command(command, file_path)
        elif sys.platform == "win32":
            os.startfile(file_path)
        elif sys.platform == "darwin":
            execute_command("open $", file_path)
        elif not webbrowser.open(file_path):
            raise webbrowser.Error("no known URL provider available")
    except Exception as error:
        log.add(_("Failed to open file path: %s"), error)
class RoomList(ServerMessage):
    def get_rooms(self, originalpos, message):
        try:
            pos, numrooms = self.get_object(message, int, originalpos)
            rooms = []
            for i in range(numrooms):
                pos, room = self.get_object(message, str, pos)
                rooms.append([room, None])
            pos, numusers = self.get_object(message, int, pos)
            for i in range(numusers):
                pos, usercount = self.get_object(message, int, pos)
                rooms[i][1] = usercount
