    lines = 0
    start = pos
    result = _Result()
    if pos >= maximum:
        return result
    marker = charCodeAt(string, pos)
    if marker != 0x22 and marker != 0x27 and marker != 0x28:
        return result
    pos += 1
    if marker == 0x28:
        marker = 0x29
    while pos < maximum:
        code = charCodeAt(string, pos)
        if code == marker:
            title = string[start + 1 : pos]
            title = unescapeAll(title)
            result.pos = pos + 1
            result.lines = lines
            result.str = title
            result.ok = True
            return result
        elif code == 0x28 and marker == 0x29:
            return result
        elif code == 0x0A:
            lines += 1
